[
  {
    "text": "The compiled DiT forward pass of SANA-Video 2.0 is 3.2 times faster than a matched full-softmax baseline at 720p resolution for a 60-second video.",
    "topic": "Performance"
  },
  {
    "text": "Full-stack Sol-Engine optimization, including kernel fusion, caching, and sparse attention, further accelerates the hardware-friendly backbone by 3.58 times.",
    "topic": "Optimization"
  },
  {
    "text": "With full-stack optimization, the 5B SANA-Video 2.0 pipeline achieves a processing time of 13.06 seconds for a 720p video of 5 seconds, making it 120 times faster than Wan 2.2-A14B on a single H100 GPU.",
    "topic": "Speed Comparison"
  },
  {
    "text": "The hybrid design of SANA-Video 2.0 recovers softmax-level expressiveness while reducing computational cost, enabling scalable generation of long, high-resolution videos.",
    "topic": "Expressiveness and Scalability"
  },
  {
    "text": "Self-attention mechanisms are identified as the main bottleneck in high-resolution video generation for long spatio-temporal sequences using Video Diffusion Transformers.",
    "topic": "Bottleneck Identification"
  }
]
